// === Tab: leaf ===
function makeLeaf() {
	return buildGeometry('leaf', (builder) => {
		// Each spine on the leaf is a connection between two bezier
		// curves, one on the inside (a straight line in space) and
		// on the outside
		builder.cylinder(2, 140)
		const outerEdgeBezier = [
			createVector(18, 40),
			createVector(20, 30),
			createVector(30, -80),
			createVector(5, -110),
		]

		// This is a straight line in space but not in "time" (where
		// t goes from 0 to 1) so that the angles change a bit
		const innerEdgeBezier = [
			createVector(0, 45),
			createVector(0, 40),
			createVector(0, -60),
			createVector(0, -70),
		]
		const evaluateBezier = (bezier, t) => {
			return createVector(
				bezierPoint(...bezier.map((pt) => pt.x), t),
				bezierPoint(...bezier.map((pt) => pt.y), t),
			)
		}
		for (const side of [-1, 1]) {
			builder.push()
			builder.scale(side, 1)
			const numSpines = 15
			for (let i = 0; i < numSpines; i++) {
				const t = (i/(numSpines - 1))
				const inner = evaluateBezier(innerEdgeBezier, t)
				const outer = evaluateBezier(outerEdgeBezier, t)
				const mid = inner.copy().add(outer).div(2)
				const angle = createVector(1, 0).angleBetween(outer.copy().sub(inner))
				const r = outer.copy().sub(inner).mag()
				builder.push()
				builder.translate(mid.x, mid.y)
				builder.rotateZ(angle + PI/2)
				builder.cylinder(1, r)
				builder.pop()
			}
			builder.pop()
		}
	})
}

// === Tab: scatterLeaves ===
function scatterLeaves() {
	const leaves = []

	// Position a few ovals on the screen
	const locations = []
	for (let i = 0; i < 8; i++) {
		locations.push({
			x: random(-width, width) * 0.8,
			y: random(-height, height) * 0.8,
			rx: random(100, 500),
			ry: random(100, 500),
			r: random(TWO_PI),
		})
	}

	// Add a leaf to a random oval using a Gaussian distribution within
	// each
	for (let i = 0; i < 260; i++) {
		const location = random(locations)
		const localX = randomGaussian(0, location.rx / 3)
		const localY = randomGaussian(0, location.ry / 3)
		const pos = createVector(localX, localY).rotate(location.r).add(location.x, location.y)
		leaves.push({
			pos: createVector(pos.x, pos.y, random(-300, 0)),
			rx: 0,
			ry: 0,
			rz: random(TWO_PI),
		})
	}

	return leaves
}

// === Tab: tintShader ===
function makeTintShader() {
	const vert = `
		precision highp float;
		precision highp int;

		attribute vec3 aPosition;
		attribute vec2 aTexCoord;

		uniform mat4 uModelViewMatrix;
		uniform mat4 uProjectionMatrix;

		varying vec2 vTexCoord;
		varying vec3 modelCoord;

		void main(void) {
			vec3 adjustedPos = aPosition;
			modelCoord = aPosition;

			vec4 viewModelPosition = uModelViewMatrix * vec4(aPosition, 1.0);
			gl_Position = uProjectionMatrix * viewModelPosition;  
			vTexCoord = aTexCoord;
		}
	`

	const frag = `
		precision highp float;
		precision highp int;

		uniform sampler2D tex;
		uniform vec3 inkColor;
		uniform vec3 bgColor;

		varying vec2 vTexCoord;
		varying vec3 modelCoord;

		float rand(float n) {
			return fract(sin(n) * 43758.5453123);
		}
		float rand(vec2 n) { 
			return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);
		}
		float noise(float p) {
			float fl = floor(p);
			float fc = fract(p);
			return mix(rand(fl), rand(fl + 1.0), fc);
		}
		float noise(vec2 n) {
			const vec2 d = vec2(0.0, 1.0);
			vec2 b = floor(n);
			vec2 f = smoothstep(vec2(0.0), vec2(1.0), fract(n));
			return mix(mix(rand(b), rand(b + d.yx), f.x), mix(rand(b + d.xy), rand(b + d.yy), f.x), f.y);
		}

		void main(void) {
			vec3 rgb = texture2D(tex, vTexCoord).xyz;
			float brightness = rgb.b;

			// Add some noise dithering
			float mappedBrightness = smoothstep(0.5, 1.1, brightness + rand(modelCoord.xy * 2.)*0.5-0.05);

			// Remap the dithered brightness to a gradient between the dark and
			// light color
			gl_FragColor = vec4(mix(inkColor, bgColor, 1.-mappedBrightness), 1.);
		}
	`

	return [vert, frag]
}

// === Tab: mySketch ===
/*

An entry for @sableRaph's Weekly Creative Coding Challenge
for the theme "single hue"

This is a generative version of the album art for
R.E.M.'s Green: https://en.wikipedia.org/wiki/Green_(R.E.M._album)

*/

Framebuffer.forceWebGL1 = true

let leaf
let blur
let blurResult
let tintShader
let font

function preload() {
	// Syncopate 700
	font = loadFont('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/default_texture.png')
}

function setup() {
	createCanvas(600, 600, WEBGL)
	leaf = makeLeaf()
	locations = scatterLeaves()
	blur = createGaussianBlurRenderer()
	blur.setIntensity(0.08)
	blur.setSamples(20)
	blurResult = createFramebuffer()
	tintShader = createShader(...makeTintShader())
}

function mouseClicked() {
	locations = scatterLeaves()
}

function draw() {
	const t = millis()
	clear()

	// Draw all the leaves with the ones at the back more blurred
	blurResult.draw(() => {
		clear()
		blur.draw(() => {
			clear()
			background(255)
			ambientLight(128, 128, 128)
			directionalLight(128, 128, 128, 0.5, 0, -1)
			noStroke()
			ambientMaterial(20)
			specularMaterial(20)
			shininess(100)
			blur.focusHere()

			// Rotate a bit based on the mouse position
			rotateY(map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, -PI, PI)*0.02)
			rotateX(-map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, -PI, PI)*0.02)

			// Draw each leaf in its spot with some time based rotation
			locations.forEach((loc, i) => {
				push()
				translate(loc.pos.x, loc.pos.y, loc.pos.z)
				rotateX(loc.rx + 0.3*map(noise(t*0.0005, i*100, 0), 0, 1, -1, 1))
				rotateY(loc.ry + 0.3*map(noise(t*0.0005, i*100, 1000), 0, 1, -1, 1))
				rotateZ(loc.rz)
				model(leaf)
				pop()
			})
		})
	})

	// I want a black background but this makes OpenProcessing glitch out :')
	// background(0)

	// Use a shader to add some noise dithering and to remap the colors
	// from black and white to the album's color scheme
	push()
	noStroke()
	shader(tintShader)
	tintShader.setUniform('inkColor', color('#fab31b')._array)
	tintShader.setUniform('bgColor', color('#a3781c')._array)
	tintShader.setUniform('tex', blurResult.color)
	plane(width, -height)
	pop()

	// Add the title
	push()
	fill(0)
	noStroke()
	textFont(font)
	textSize(120)
	textLeading(160)
	textAlign(CENTER, CENTER)
	text('GREEN\nR.E.M.', -width/2, -height/2, width, height)
	pop()
}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

